// AM purchase_orders -> canonical PurchaseOrder[]. Falls back to a
// realistic sample if AM has none yet (no vendor POs entered in the test
// company). Mirrors adapters/erp/apparelmagic/lib/parsePurchaseOrder.js --
// keep in sync if that file changes. Unlike pick tickets, no separate
// Inventory combine is needed here -- the 943 deliberately sends no UPC
// (DCG's own spec: "UPC is not sent anymore"), so parsePurchaseOrder.js's
// existing fields are sufficient.
const num = (v) => (v == null || v === '' ? null : Number(v));
const resp = $input.first().json.response || [];
const records = resp.length ? resp : [{
  purchase_order_id: 'SAMPLE-4000', vendor_id: '2', warehouse_id: '1',
  date: new Date().toISOString().slice(0,10), date_start: null, date_due: new Date(Date.now() + 30*24*60*60*1000).toISOString().slice(0,10),
  shipping_address_override: '0', address_1: '111 Main Street', address_2: null, city: 'West Palm Beach', state: 'FL', postal_code: '33405', country: 'USA',
  ship_via: 'PARCEL', tracking_number: 'SAMPLE-TRACK-123', qty: '100', qty_received: '0', qty_open: '100', amount: '2500.00',
  purchase_order_items: [ { product_id: '4', sku_id: '4', attr_2: 'BLK', size: 'M100', style_number: 'JEAN1', description: 'Classic Denim Jean', qty: '100', qty_open: '100', qty_received: '0', unit_cost: '9.695', amount: '969.50' } ]
}];
const isSample = resp.length === 0;

return records.map((record) => ({ json: { isSample, purchaseOrder: {
  purchaseOrderId: record.purchase_order_id, vendorId: record.vendor_id, warehouseId: record.warehouse_id || null,
  date: record.date ?? null, dateStart: record.date_start || null, dateDue: record.date_due || null,
  shipTo: { address1: record.shipping_address_override === '1' ? record.shipping_address_1 : record.address_1, address2: record.shipping_address_override === '1' ? record.shipping_address_2 : record.address_2, city: record.shipping_address_override === '1' ? record.shipping_city : record.city, state: record.shipping_address_override === '1' ? record.shipping_state : record.state, zip: record.shipping_address_override === '1' ? record.shipping_postal_code : record.postal_code, country: record.shipping_address_override === '1' ? record.shipping_country : record.country },
  shipVia: record.ship_via || null, trackingNumber: record.tracking_number || null,
  qty: num(record.qty), qtyReceived: num(record.qty_received), qtyOpen: num(record.qty_open), amount: num(record.amount),
  lines: (record.purchase_order_items || []).map((item) => ({ productId: item.product_id, skuId: item.sku_id, color: item.attr_2 || null, size: item.size || null, styleNumber: item.style_number || null, description: item.description || null, qty: num(item.qty), qtyOpen: num(item.qty_open), qtyReceived: num(item.qty_received), unitCost: num(item.unit_cost), amount: num(item.amount) })),
} } }));

// Ports adapters/edi/x12-dcg/lib/{envelope,itemCode,build943}.js into a
// single n8n Code node (Code nodes can't import repo files). Keep in sync
// with those files if the builder logic changes -- see
// adapters/edi/x12-dcg/schema-notes.md for the full field mapping and every
// open question flagged below. Runs once PER purchase order -- each PO is
// its own 943 shipment-advice transaction, matching 940's per-shipment
// pattern (not batched like 888).
const ELEMENT_SEP = '|';
const SEGMENT_TERM = '\n';
function segment(...elements) { return elements.map((e) => (e ?? '')).join(ELEMENT_SEP); }
function pad15(value) { return String(value ?? '').padEnd(15, ' ').slice(0, 15); }

function buildEnvelope(cfg, bodySegments) {
  const {
    senderQualifier = 'ZZ', senderId, receiverQualifier = 'ZZ', receiverId,
    interchangeControlNumber, groupControlNumber, transactionSetControlNumber = '0001',
    functionalIdentifierCode, transactionSetIdentifierCode,
    responsibleAgencyCode = 'X', versionReleaseIndustryCode = '004010',
    interchangeControlVersion = '00401', usageIndicator = 'T', date = new Date(),
  } = cfg;
  const yy = String(date.getUTCFullYear()).slice(2);
  const mm = String(date.getUTCMonth() + 1).padStart(2, '0');
  const dd = String(date.getUTCDate()).padStart(2, '0');
  const hh = String(date.getUTCHours()).padStart(2, '0');
  const min = String(date.getUTCMinutes()).padStart(2, '0');
  const isaDate = `${yy}${mm}${dd}`;
  const gsDate = `${date.getUTCFullYear()}${mm}${dd}`;
  const time = `${hh}${min}`;
  const isaControl = String(interchangeControlNumber).padStart(9, '0');
  const isa = segment('ISA', '00', pad15(''), '00', pad15(''), senderQualifier, pad15(senderId), receiverQualifier, pad15(receiverId), isaDate, time, 'U', interchangeControlVersion, isaControl, '0', usageIndicator, '>');
  const gs = segment('GS', functionalIdentifierCode, senderId, receiverId, gsDate, time, String(groupControlNumber), responsibleAgencyCode, versionReleaseIndustryCode);
  const st = segment('ST', transactionSetIdentifierCode, transactionSetControlNumber);
  const se = segment('SE', String(bodySegments.length + 2), transactionSetControlNumber);
  const ge = segment('GE', '1', String(groupControlNumber));
  const iea = segment('IEA', '1', isaControl);
  return [isa, gs, st, ...bodySegments, se, ge, iea].join(SEGMENT_TERM) + SEGMENT_TERM;
}

function vendorItemNumber(styleNumber, color, size) {
  return `${styleNumber ?? ''}${color ?? ''}${size ?? ''}`.toUpperCase().replace(/\s+/g, '');
}
function ccyymmdd(isoDate) { return isoDate ? isoDate.replace(/-/g, '') : null; }
function ccyymmddFromDate(date) {
  const yyyy = date.getUTCFullYear();
  const mm = String(date.getUTCMonth() + 1).padStart(2, '0');
  const dd = String(date.getUTCDate()).padStart(2, '0');
  return `${yyyy}${mm}${dd}`;
}

function buildW06(purchaseOrder, { transactionTypeCode, date }) {
  const orderNumber = purchaseOrder.purchaseOrderId ?? '';
  return segment('W06', 'F', orderNumber, ccyymmddFromDate(date), orderNumber, '', '', '', '', '', '', transactionTypeCode);
}
function buildWarehouseLoop(warehouseCode) {
  if (!warehouseCode) return [];
  return [segment('N1', 'WH', warehouseCode), segment('PER', 'WH', warehouseCode)];
}
function buildHeaderN9(purchaseOrder, { orderReference }) {
  const segs = [];
  if (orderReference) segs.push(segment('N9', 'CO', orderReference));
  if (purchaseOrder.shipVia) segs.push(segment('N9', 'KK', purchaseOrder.shipVia));
  if (purchaseOrder.trackingNumber) segs.push(segment('N9', 'SI', purchaseOrder.trackingNumber));
  return segs;
}
function buildG62(purchaseOrder) {
  const expected = ccyymmdd(purchaseOrder.dateDue);
  return expected ? [segment('G62', '17', expected)] : [];
}
function buildLineSegments(line, index, { brandDescription, brandCode }) {
  const lineNumber = String(index + 1).padStart(6, '0');
  const segs = [
    segment('W04', String(line.qty ?? ''), 'EA', '', 'VN', vendorItemNumber(line.styleNumber, line.color, line.size), 'IT', line.styleNumber ?? '', '', '', '', lineNumber),
  ];
  if (line.description) segs.push(segment('G69', line.description));
  if (brandDescription) segs.push(segment('N9', 'DI', brandDescription));
  if (brandCode) segs.push(segment('N9', 'DV', brandCode));
  return segs;
}
function build943(purchaseOrder, options = {}) {
  const { warehouseCode, orderReference, brandDescription, brandCode, transactionTypeCode = 'PO', date = new Date(), envelope = {} } = options;
  const body = [
    buildW06(purchaseOrder, { transactionTypeCode, date }),
    ...buildWarehouseLoop(warehouseCode),
    ...buildHeaderN9(purchaseOrder, { orderReference }),
    ...buildG62(purchaseOrder),
  ];
  (purchaseOrder.lines ?? []).forEach((line, index) => { body.push(...buildLineSegments(line, index, { brandDescription, brandCode })); });
  return buildEnvelope({ functionalIdentifierCode: 'AR', transactionSetIdentifierCode: '943', ...envelope, date }, body);
}

const purchaseOrder = $json.purchaseOrder;
const now = new Date();
const controlNumber = Number(String(Date.now()).slice(-9));

const x12 = build943(purchaseOrder, {
  warehouseCode: '001', // TBD -- confirm the real DCG-side warehouse/location code with Chi Cao, see schema-notes.md
  date: now,
  envelope: {
    senderId: 'SCLFOOTWEAR',  // TBD -- confirm exact ISA sender ID DCG expects for SCL
    receiverId: 'DCG',        // TBD -- confirm exact ISA receiver ID DCG expects for SCL
    interchangeControlNumber: controlNumber,
    groupControlNumber: controlNumber,
    usageIndicator: 'T', // TEST -- flip to 'P' only once DCG confirms this is a real send
  },
});

const fileName = `SCL_943_${String(purchaseOrder.purchaseOrderId).replace(/[^a-zA-Z0-9-]/g, '_')}_${now.toISOString().replace(/[:.]/g, '-')}.txt`;
const dedupeKey = `943|${purchaseOrder.purchaseOrderId}`;

return {
  json: {
    fileName, dedupeKey, correlationId: dedupeKey,
    purchaseOrderId: purchaseOrder.purchaseOrderId, vendorId: purchaseOrder.vendorId,
    docType: '943', direction: 'outbound', status: 'created',
    externalIds: JSON.stringify({ controlNumber, purchaseOrderId: purchaseOrder.purchaseOrderId, isSample: $json.isSample }),
  },
  binary: {
    data: { data: Buffer.from(x12, 'utf-8').toString('base64'), mimeType: 'text/plain', fileName },
  },
};

// Postgres nodes don't reliably pass through binary data from their input
// item, so pull the X12 file's binary back from Build 943 X12 by name, and
// merge in the correlation_id Claim & Log just produced (needed by Mark Sent).
const meta = $('Build 943 X12').item.json;
const claim = $json;
return [{
  json: { ...meta, correlationId: claim.correlation_id },
  binary: $('Build 943 X12').item.binary,
}];
